    "rollupSummary.state": {
        parameters: {
            query?: never;
            header?: never;
            path: {
                /** @description The state ID */
                state: number;
            };
            cookie?: never;
        };
        requestBody?: never;
        responses: {
            200: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "application/json": {
                        data: {
                            node: {
                                /** @constant */
                                level: "state";
                                id: number;
                                name: string;
                                parent: {
                                    /** @constant */
                                    level: "country";
                                    id: null;
                                    /** @constant */
                                    name: "Nigeria";
                                };
                                /** @description The state's own store (its Stock Card is not part of this rollup). */
                                store: {
                                    id: number;
                                    name: string;
                                };
                            };
                            child_count: number;
                            facility_count: number;
                            /** @description Number of facilities with at least one product carrying each flag. */
                            facility_counts: {
                                stock_out: number;
                                expired: number;
                                low_stock: number;
                                expiring_soon: number;
                            };
                            /** @description Facilities by their most serious issue, each counted once. */
                            facility_status: {
                                stock_out: number;
                                low_stock: number;
                                reorder: number;
                                ok: number;
                                no_data: number;
                            };
                            products: components["schemas"]["ProductRollupResource"][];
                            /** @description Child LGAs, worst first. */
                            children: components["schemas"]["AreaStockSummaryResource"][];
                        };
                    };
                };
            };
            401: components["responses"]["AuthenticationException"];
            403: components["responses"]["AuthorizationException"];
            404: components["responses"]["ModelNotFoundException"];
        };
    };
